{
  "contract": "GoodMorning",
  "closure": {
    "site_function": "swapBack",
    "site_call": ".addLiquidityETH",
    "functions": [
      "transfer",
      "transferFrom",
      "approve",
      "_transferFrom",
      "_basicTransfer",
      "takeFeeInProportions"
    ],
    "justification": "Includes all functions that can modify _rOwned or _totalProportion, which are relevant to the target property."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom",
      "approve",
      "_transferFrom",
      "_basicTransfer",
      "takeFeeInProportions"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1,
      "approve": 1,
      "_transferFrom": 1,
      "_basicTransfer": 1,
      "takeFeeInProportions": 1
    }
  },
  "phases": {
    "function": "swapBack",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before_addLiquidityETH"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_addLiquidityETH",
      "to_marker": "after_addLiquidityETH"
    },
    "post": {
      "name": "post",
      "from_marker": "after_addLiquidityETH",
      "to_marker": "exit"
    },
    "linearization_point": "after_addLiquidityETH"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount in-flight during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__rOwned == _totalProportion + inFlight",
    "stable_formula": "_sum__rOwned == _totalProportion",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__rOwned == _totalProportion",
    "rule": "The exposure invariant ensures conservation of _rOwned across the callback window."
  }
}
